triggerStop() {
  if (this.stopTriggered) {
    return;
  }
  this.stopTriggered = true;
  this.finishReason = "abort";
  if (!this.conversation.isTextCompletion) {
    this.conversation.finishReply(this.outputMessage);
  }
}

